// hp41_segments.h -- the HP-41 display's characters as segments, to draw
// one at any size (the Character table's details box): 14 segments, the
// dot, the comma's tail and the colon's upper dot, each a few filled
// triangles, and for each HP-41 code (0..127) the ones that are lit. In
// the font's units (41charset_x.ttf: a cell 900 wide, 0..819 high, y up;
// the punctuation at the cell's right edge).
//
// src/hp41_segments.cpp is generated by resources/fonts/hp41_segments.py.
#pragma once
#include <cstdint>

namespace hipi {

struct Hp41Triangle { std::int16_t x0, y0, x1, y1, x2, y2; };

constexpr int kHp41Shapes = 17;                    // 0..13 segments, 14 dot, 15 comma tail, 16 colon's top
constexpr int kHp41CellW = 900, kHp41FontH = 819; // a character's cell (its punctuation reaches x 860, the comma y -78)

extern const Hp41Triangle kHp41Triangles[];
extern const std::uint8_t kHp41ShapeFirst[kHp41Shapes + 1];
extern const std::uint32_t kHp41Lit[128];         // bit k: shape k lit

}  // namespace hipi
